create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id),display_name text not null,role text not null check(role in ('super_admin','admin')),enabled boolean not null default true,created_at timestamptz not null default now());
create function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and enabled and role in ('super_admin','admin')) $$;
create function public.is_super() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from profiles where id=auth.uid() and enabled and role='super_admin') $$;
create table public.services(id uuid primary key default gen_random_uuid(),name text not null,slug text not null unique check(slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$' and slug not in ('admin','api','checkout','track','login','new','settings','privacy')),description text not null default '',details text not null default '',price numeric(14,2) not null check(price>=0),currency text not null check(currency in ('USD','SYP','EUR','TRY')),status text not null default 'draft' check(status in ('draft','active','archived')),image_path text,form_schema jsonb not null default '[]',sort_order integer not null default 0,duration text not null default '',instructions text not null default '',starts_at timestamptz,ends_at timestamptz,max_orders integer check(max_orders>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(ends_at is null or starts_at is null or ends_at>starts_at));
create table public.campaigns(like public.services including all);

create table public.campaign_services(campaign_id uuid references campaigns(id) on delete cascade,service_id uuid references services(id),primary key(campaign_id,service_id));
create table public.form_fields(id uuid primary key default gen_random_uuid(),campaign_id uuid references campaigns(id),service_id uuid references services(id),position integer not null,definition jsonb not null,check(num_nonnulls(campaign_id,service_id)=1));
create table public.settings(id text primary key default 'main' check(id='main'),value jsonb not null default '{"platform_name":"مدار","currency":"USD","timezone":"Asia/Damascus","date_format":"dd/MM/yyyy","accepting_orders":false,"sham_name":"","sham_account":"","payment_instructions":"","whatsapp_enabled":false,"whatsapp_recipient":"","whatsapp_language":"ar","templates":{},"notification_events":["order_created","payment_submitted","payment_approved"],"recipient_consent":false}');
insert into settings(id) values('main');
create sequence public.order_numbers;
create table public.orders(id uuid primary key default gen_random_uuid(),order_number text not null unique default ('CF-'||lpad(nextval('public.order_numbers')::text,8,'0')),customer_name text not null,phone text not null,campaign_id uuid references campaigns(id),service_id uuid references services(id),item_name text not null,amount numeric(14,2) not null check(amount>=0),currency text not null,status text not null default 'pending_payment' check(status in ('pending_payment','payment_review','paid','processing','completed','payment_rejected','cancelled','expired')),payment_status text not null default 'pending' check(payment_status in ('pending','review','approved','rejected')),form_snapshot jsonb not null,answers jsonb not null,access_hash text not null,idempotency_key uuid not null unique,notes text not null default '',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(campaign_id is not null or service_id is not null));
create table public.order_answers(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),field_id text not null,value jsonb,unique(order_id,field_id));
create table public.attachments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),path text not null unique,mime text not null,size integer not null check(size>0 and size<=5242880),purpose text not null check(purpose in ('receipt','form')),created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),attachment_id uuid not null references attachments(id),status text not null default 'review' check(status in ('review','approved','rejected')),reference text,review_reason text,reviewed_by uuid references profiles(id),reviewed_at timestamptz,created_at timestamptz not null default now());
create unique index one_review_payment on payments(order_id) where status='review';
create unique index one_approved_payment on payments(order_id) where status='approved';
create table public.payment_reviews(id uuid primary key default gen_random_uuid(),payment_id uuid not null references payments(id),decision text not null check(decision in ('approved','rejected')),reason text,reference text,actor uuid not null references profiles(id),created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(),order_id uuid references orders(id),actor uuid references profiles(id),action text not null,metadata jsonb not null default '{}',created_at timestamptz not null default now());
create table public.notification_outbox(id uuid primary key default gen_random_uuid(),order_id uuid not null references orders(id),event text not null,dedupe_key text not null unique,status text not null default 'pending' check(status in ('pending','sending','sent','failed','disabled','uncertain')),attempts integer not null default 0,next_attempt_at timestamptz not null default now(),locked_at timestamptz,lock_token uuid,last_error text,external_id text,created_at timestamptz not null default now());
create table public.whatsapp_messages(id uuid primary key default gen_random_uuid(),outbox_id uuid not null references notification_outbox(id),external_id text not null unique,status text not null default 'sent',updated_at timestamptz not null default now(),created_at timestamptz not null default now());
create table public.webhook_events(id text primary key,payload jsonb not null,created_at timestamptz not null default now());
create table public.rate_limits(key text primary key,hits integer not null default 1,window_start timestamptz not null default now());
create index orders_created on orders(created_at desc);
create index orders_state on orders(status,created_at desc);
create index orders_campaign on orders(campaign_id,created_at desc);
create index orders_service on orders(service_id,created_at desc);
create index orders_phone on orders(phone);
create index outbox_due on notification_outbox(status,next_attempt_at);
create index payments_order on payments(order_id,created_at desc);
create index audit_order on audit_logs(order_id,created_at desc);
create function public.rate_limit(p_key text,p_max integer) returns boolean language plpgsql security definer set search_path=public as $$ declare v integer;begin insert into rate_limits(key) values(p_key) on conflict(key) do update set hits=case when rate_limits.window_start<now()-interval '1 minute' then 1 else rate_limits.hits+1 end,window_start=case when rate_limits.window_start<now()-interval '1 minute' then now() else rate_limits.window_start end returning hits into v;return v<=p_max;end $$;
create function public.enqueue(p_order uuid,p_event text,p_key text) returns void language sql security definer set search_path=public as $$ insert into notification_outbox(order_id,event,dedupe_key,status) select p_order,p_event,p_key,case when (value->>'whatsapp_enabled')::boolean and coalesce((value->'notification_events') ? p_event,false) then 'pending' else 'disabled' end from settings where id='main' on conflict(dedupe_key) do nothing $$;
create function public.create_order(p_kind text,p_slug text,p_service uuid,p_name text,p_phone text,p_answers jsonb,p_key uuid,p_hash text,p_schema jsonb) returns public.orders language plpgsql security definer set search_path=public as $$
declare item record;svc services;existing orders;result orders;begin
perform pg_advisory_xact_lock(hashtextextended(p_key::text,0));
select * into existing from orders where idempotency_key=p_key;if found then if existing.access_hash<>p_hash then raise exception 'طلب مكرر برمز مختلف';end if;return existing;end if;
if not exists(select 1 from settings where id='main' and value->>'accepting_orders'='true' and length(value->>'sham_account')>0) then raise exception 'استقبال الطلبات متوقف';end if;
if p_kind='campaigns' then select * into item from campaigns where slug=p_slug for update;elsif p_kind='services' then select * into item from services where slug=p_slug for update;else raise exception 'نوع غير صالح';end if;
if item.id is null or item.status<>'active' or (item.starts_at is not null and item.starts_at>now()) or (item.ends_at is not null and item.ends_at<now()) then raise exception 'العرض غير متاح';end if;
if item.form_schema<>p_schema then raise exception 'تم تحديث النموذج، أعد تحميل الصفحة';end if;
if item.max_orders is not null and (select count(*) from orders where (campaign_id=item.id or service_id=item.id) and status not in ('cancelled','expired'))>=item.max_orders then raise exception 'اكتمل العدد المتاح';end if;
if p_kind='campaigns' and p_service is not null then select s.* into svc from services s join campaign_services cs on cs.service_id=s.id where cs.campaign_id=item.id and s.id=p_service and s.status='active';if svc.id is null then raise exception 'الخدمة غير متاحة';end if;end if;
insert into orders(customer_name,phone,campaign_id,service_id,item_name,amount,currency,form_snapshot,answers,access_hash,idempotency_key) values(p_name,p_phone,case when p_kind='campaigns' then item.id end,case when p_kind='services' then item.id else svc.id end,case when svc.id is not null then item.name||' — '||svc.name else item.name end,coalesce(svc.price,item.price),coalesce(svc.currency,item.currency),item.form_schema,p_answers,p_hash,p_key) returning * into result;
insert into order_answers(order_id,field_id,value) select result.id,key,value from jsonb_each(p_answers);
insert into audit_logs(order_id,action) values(result.id,'order_created');perform enqueue(result.id,'order_created',result.id||':created');return result;end $$;
create function public.submit_payment(p_order uuid,p_hash text,p_path text,p_mime text,p_size integer) returns uuid language plpgsql security definer set search_path=public as $$ declare o orders;a uuid;p uuid;begin
select * into o from orders where id=p_order and access_hash=p_hash for update;if o.id is null or o.status not in ('pending_payment','payment_rejected') then raise exception 'لا يمكن إرسال إشعار لهذا الطلب';end if;
insert into attachments(order_id,path,mime,size,purpose) values(o.id,p_path,p_mime,p_size,'receipt') returning id into a;
insert into payments(order_id,attachment_id) values(o.id,a) returning id into p;
update orders set status='payment_review',payment_status='review',updated_at=now() where id=o.id;
insert into audit_logs(order_id,action,metadata) values(o.id,'payment_submitted',jsonb_build_object('payment_id',p));perform enqueue(o.id,'payment_submitted',p||':submitted');return p;end $$;
create function public.review_payment(p_payment uuid,p_decision text,p_reason text,p_reference text,p_actor uuid) returns void language plpgsql security definer set search_path=public as $$ declare p payments;begin
if p_decision not in ('approved','rejected') or (p_decision='rejected' and length(trim(p_reason))=0) then raise exception 'قرار أو سبب غير صالح';end if;
perform 1 from orders where id=(select order_id from payments where id=p_payment) for update;
select * into p from payments where id=p_payment for update;if p.id is null or p.status<>'review' then raise exception 'تمت مراجعة الإشعار سابقاً';end if;
if not exists(select 1 from profiles where id=p_actor and enabled) then raise exception 'غير مصرح';end if;
update payments set status=p_decision,review_reason=p_reason,reference=p_reference,reviewed_by=p_actor,reviewed_at=now() where id=p.id;
insert into payment_reviews(payment_id,decision,reason,reference,actor) values(p.id,p_decision,p_reason,p_reference,p_actor);
update orders set status=case when p_decision='approved' then 'paid' else 'payment_rejected' end,payment_status=p_decision,updated_at=now() where id=p.order_id;
insert into audit_logs(order_id,actor,action,metadata) values(p.order_id,p_actor,'payment_'||p_decision,jsonb_build_object('payment_id',p.id,'reason',p_reason));
if p_decision='approved' then perform enqueue(p.order_id,'payment_approved',p.id||':approved');end if;end $$;
create function public.update_order(p_order uuid,p_status text,p_notes text,p_actor uuid) returns void language plpgsql security definer set search_path=public as $$ declare o orders;begin
select * into o from orders where id=p_order for update;if o.id is null then raise exception 'الطلب غير موجود';end if;
if p_status<>o.status and not ((o.status='paid' and p_status='processing' and o.payment_status='approved') or (o.status='processing' and p_status='completed' and o.payment_status='approved') or (o.status in ('pending_payment','payment_rejected') and p_status in ('cancelled','expired'))) then raise exception 'انتقال حالة غير مسموح';end if;
update orders set status=p_status,notes=p_notes,updated_at=now() where id=o.id;
insert into audit_logs(order_id,actor,action,metadata) values(o.id,p_actor,'order_updated',jsonb_build_object('from',o.status,'to',p_status,'notes',p_notes));end $$;
create function public.save_catalog(p_kind text,p_id uuid,p_data jsonb,p_services uuid[],p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_id uuid:=coalesce(p_id,gen_random_uuid()); v_table text;begin
if p_kind not in ('campaigns','services') then raise exception 'غير صالح';end if;v_table:=p_kind;
execute format('insert into %I(id,name,slug,description,details,price,currency,status,image_path,form_schema,starts_at,ends_at,max_orders,sort_order,duration,instructions) values($1,$2->>''name'',$2->>''slug'',$2->>''description'',$2->>''details'',($2->>''price'')::numeric,$2->>''currency'',$2->>''status'',$2->>''image_path'',$2->''form_schema'',($2->>''starts_at'')::timestamptz,($2->>''ends_at'')::timestamptz,($2->>''max_orders'')::integer,($2->>''sort_order'')::integer,$2->>''duration'',$2->>''instructions'') on conflict(id) do update set name=excluded.name,slug=excluded.slug,description=excluded.description,details=excluded.details,price=excluded.price,currency=excluded.currency,status=excluded.status,image_path=excluded.image_path,form_schema=excluded.form_schema,starts_at=excluded.starts_at,ends_at=excluded.ends_at,max_orders=excluded.max_orders,sort_order=excluded.sort_order,duration=excluded.duration,instructions=excluded.instructions,updated_at=now()',v_table) using v_id,p_data;
if p_kind='campaigns' then delete from campaign_services where campaign_id=v_id;insert into campaign_services select v_id,unnest(p_services);end if;
delete from form_fields where campaign_id=v_id or service_id=v_id;
insert into form_fields(campaign_id,service_id,position,definition) select case when p_kind='campaigns' then v_id end,case when p_kind='services' then v_id end,(ordinality-1)::integer,value from jsonb_array_elements(p_data->'form_schema') with ordinality;
insert into audit_logs(actor,action,metadata) values(p_actor,p_kind||'_saved',jsonb_build_object('id',v_id));return v_id;end $$;
create function public.claim_notifications() returns setof notification_outbox language plpgsql security definer set search_path=public as $$ begin
-- A worker lost after an HTTP send has an ambiguous result: never auto-resend.
update notification_outbox set status='uncertain',last_error='انتهت مهلة المعالجة؛ تحقق من Meta قبل إعادة الإرسال' where status='sending' and locked_at<now()-interval '5 minutes';
return query with due as(select id from notification_outbox where status in ('pending','failed') and attempts<6 and next_attempt_at<=now() order by created_at for update skip locked limit 10) update notification_outbox n set status='sending',attempts=n.attempts+1,locked_at=now(),lock_token=gen_random_uuid() from due where n.id=due.id returning n.*;end $$;
create function public.record_webhook(p_id text,p_payload jsonb,p_external text,p_status text) returns void language plpgsql security definer set search_path=public as $$ begin
insert into webhook_events(id,payload) values(p_id,p_payload) on conflict do nothing;if not found then return;end if;
update whatsapp_messages set status=p_status,updated_at=now() where external_id=p_external and (case p_status when 'read' then 4 when 'delivered' then 3 when 'failed' then 2 else 1 end)>=(case status when 'read' then 4 when 'delivered' then 3 when 'failed' then 2 else 1 end);end $$;
create function public.dashboard_data() returns jsonb language sql security definer set search_path=public as $$ select jsonb_build_object('total',(select count(*) from orders),'today',(select count(*) from orders where created_at>=(date_trunc('day',now() at time zone coalesce((select value->>'timezone' from settings where id='main'),'Asia/Damascus')) at time zone coalesce((select value->>'timezone' from settings where id='main'),'Asia/Damascus'))),'states',(select coalesce(jsonb_object_agg(status,n),'{}') from(select status,count(*) n from orders group by status)t),'revenue',(select coalesce(jsonb_object_agg(currency,total),'{}') from(select currency,sum(amount) total from orders where payment_status='approved' group by currency)t),'campaigns',(select count(*) from campaigns where status='active'),'services',(select count(*) from services where status='active'),'days',(select coalesce(jsonb_agg(t order by day),'[]') from(select (created_at at time zone 'Asia/Damascus')::date day,count(*) orders from orders where created_at>now()-interval '30 days' group by 1)t),'daily_revenue',(select coalesce(jsonb_agg(t order by day),'[]') from(select (created_at at time zone 'Asia/Damascus')::date day,currency,sum(amount) revenue from orders where payment_status='approved' and created_at>now()-interval '30 days' group by 1,2)t),'top_campaigns',(select coalesce(jsonb_agg(t),'[]') from(select c.name,count(o.id) orders from campaigns c join orders o on o.campaign_id=c.id group by c.id order by count(o.id) desc limit 5)t),'top_services',(select coalesce(jsonb_agg(t),'[]') from(select s.name,count(o.id) orders from services s join orders o on o.service_id=s.id group by s.id order by count(o.id) desc limit 5)t)) $$;
-- No public direct reads, including orders. Public traffic goes through validated server routes.
do $$ declare t text;begin foreach t in array array['profiles','campaigns','services','campaign_services','form_fields','orders','order_answers','payments','payment_reviews','attachments','whatsapp_messages','notification_outbox','audit_logs','settings','webhook_events','rate_limits'] loop execute format('alter table public.%I enable row level security',t);end loop;end $$;
create policy profile_self on profiles for select to authenticated using(id=auth.uid() or is_super());
-- Application administration is deliberately server mediated; browser JWTs have no write policies.
create policy admin_orders_read on orders for select to authenticated using(is_admin());
create policy admin_catalog_read on campaigns for select to authenticated using(is_admin());
create policy admin_services_read on services for select to authenticated using(is_admin());
revoke execute on all functions in schema public from public,anon,authenticated;
grant execute on function is_admin(),is_super() to authenticated;
grant execute on all functions in schema public to service_role;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('private-assets','private-assets',false,5242880,array['image/png','image/jpeg','application/pdf']) on conflict(id) do nothing;
-- No storage policies for anon/authenticated; files are accessed via server authorization and short-lived signed URLs.
